use clap::Parser;
#[derive(Parser)]
struct Cli {
    name: String,
    #[arg(short, long)]
    verbose: bool,
}
fn main() {
    let cli = Cli::parse();
    println!("Hello, {}!", cli.name);
}

pub fn greet(name: &str) -> String {
    format!("Hello, {}!", name)
}

pub fn add(a: i32, b: i32) -> i32 { a + b }

use rust_cli::greet;
#[test]
fn test_greet() {
    assert_eq!(greet("World"), "Hello, World!");
}
